use ruststream::memory::MemoryBroker;
use ruststream::runtime::{AppInfo, RustStream};

use crate::orders::handle;

#[ruststream::app]
fn app() -&gt; RustStream {
    RustStream::new(AppInfo::new("orders-service", "0.1.0")).with_broker(MemoryBroker::new(), |b| {
        b.include(handle);
    })
}
</code></pre> src/main.rs<pre><code>mod orders;

use std::error::Error;

use ruststream::memory::prelude::*;

use crate::orders::Receive;

fn app() -&gt; RustStream {
    RustStream::new(AppInfo::new("orders-service", "0.1.0")).with_broker(MemoryBroker::new(), |b| {
        b.include(subscriber("orders", Receive).build());
    })
}

#[tokio::main]
async fn main() -&gt; Result&lt;(), Box&lt;dyn Error&gt;&gt; {
    app().run().await?;
    Ok(())
}
</code></pre> <p>Codec defaults</p> <p><code>include</code> decodes with the default codec, so it needs no codec argument. The default is <code>json</code> when the feature is enabled, otherwise <code>cbor</code>, otherwise <code>msgpack</code>. You can set one codec for all the broker's handlers at once with <code>with_broker_codec(broker, codec, |b| ...)</code>. See Codecs for the full resolution rules.</p> <p>Run it:</p> <pre><code>cargo run -- run
</code></pre>

